window.RF_FULL=window.RF_FULL||{};window.RF_FULL["plenum17-2024"]=[
["0","Преамбула","","","ОБ ОТДЕЛЬНЫХ ВОПРОСАХ, ВОЗНИКАЮЩИХ У СУДОВ ПРИ РАССМОТРЕНИИ ДЕЛ ОБ АДМИНИСТРАТИВНЫХ ПРАВОНАРУШЕНИЯХ, ПОСЯГАЮЩИХ НА УСТАНОВЛЕННЫЙ ПОРЯДОК ИНФОРМАЦИОННОГО ОБЕСПЕЧЕНИЯ ВЫБОРОВ И РЕФЕРЕНДУМОВ В связи с вопросами, возникающими в судебной практике при рассмотрении дел об административных правонарушениях, посягающих на установленный порядок информационного обеспечения выборов и референдумов, Пленум Верховного Суда Российской Федерации, руководствуясь статьей 126 Конституции Российской Федерации, статьями 2 и 5 Федерального конституционного закона от 5 февраля 2014 года N 3-ФКЗ \"О Верховном Суде Российской Федерации\", постановляет дать следующие разъяснения."],
["1","Избирательные права, право на участие в референдуме граждан Российской Федерации и их объединений, а также установленный порядок подготовки и…","","","1. Избирательные права, право на участие в референдуме граждан Российской Федерации и их объединений, а также установленный порядок подготовки и проведения выборов и референдумов в Российской Федерации подлежат охране посредством принятия мер, направленных на пресечение их нарушения и привлечение виновных лиц к административной ответственности, установленной Кодексом Российской Федерации об административных правонарушениях (далее - КоАП РФ, Кодекс).\nПорядок проведения выборов и референдумов на территории Российской Федерации определяется законодательством Российской Федерации о выборах и референдумах, которое составляют Конституция Российской Федерации, Федеральный конституционный закон от 28 июня 2004 года N 5-ФКЗ \"О референдуме Российской Федерации\", Федеральный закон от 12 июня 2002 года N 67-ФЗ \"Об основных гарантиях избирательных прав и права на участие в референдуме граждан Российской Федерации\" (далее - Закон об основных гарантиях избирательных прав), иные федеральные законы, конституции (уставы), законы субъектов Российской Федерации, иные нормативные правовые акты о выборах и референдумах, принимаемые в Российской Федерации, в том числе уставы муниципальных образований, нормативные акты избирательных комиссий, комиссий референдума.\nЗаконом об основных гарантиях избирательных прав определяются основные условия, правила и процедуры, обеспечивающие реализацию избирательных прав и права на участие в референдуме граждан Российской Федерации. Федеральными конституционными законами, иными федеральными законами, законами субъектов Российской Федерации могут устанавливаться гарантии избирательных прав и права на участие в референдуме граждан Российской Федерации, дополняющие гарантии, установленные Законом об основных гарантиях избирательных прав (статья 1, подпункт 11 статьи 2, пункты 1 и 2 статьи 11, пункт 3.1 статьи 48 Закона об основных гарантиях избирательных прав)."],
["2","Выборы и референдум являются формами прямого волеизъявления граждан Российской Федерации","","","2. Выборы и референдум являются формами прямого волеизъявления граждан Российской Федерации. Сведения любого характера, связанные с их подготовкой и проведением, могут оказывать воздействие на выбор гражданина при реализации его активного избирательного права и права на участие в референдуме. В связи с этим информационное обеспечение выборов и референдумов должно способствовать осознанному волеизъявлению граждан, гласности выборов и референдумов и гарантируется условиями, правилами и процедурами, предусмотренными Законом об основных гарантиях избирательных прав (подпункты 9, 11, 53 статьи 2, пункт 3 статьи 3, статья 44 Закона об основных гарантиях избирательных прав).\nОбратить внимание судов на то, что информационное обеспечение выборов и референдумов включает информирование избирателей, участников референдума, а также предвыборную агитацию, представляющую собой деятельность, имеющую целью побудить или побуждающую избирателей к голосованию за кандидата, кандидатов, список, списки кандидатов или против него (них) в период избирательной кампании, и агитацию по вопросам референдума - деятельность, имеющую целью побудить или побуждающую участников референдума поддержать инициативу проведения референдума либо отказаться от такой поддержки, голосовать либо отказаться от голосования на референдуме, поддержать либо отвергнуть вынесенный на референдум вопрос в период кампании референдума (подпункты 3, 4 статьи 2, статьи 44, 45 Закона об основных гарантиях избирательных прав).\nНарушение правил, условий и процедур, гарантирующих информационное обеспечение выборов и референдумов, является основанием для привлечения к административной ответственности, предусмотренной в том числе статьями 5.5, 5.8, 5.10, 5.11, 5.12, 5.48 КоАП РФ, при наличии вины лица, в отношении которого ведется производство по делу об административном правонарушении."],
["3","Законодательство о выборах и референдумах закрепляет требования к участию средств массовой информации и иных лиц в информационном обеспечении выборов…","","","3. Законодательство о выборах и референдумах закрепляет требования к участию средств массовой информации и иных лиц в информационном обеспечении выборов и референдумов, в частности к порядку опубликования (обнародования) материалов, связанных с подготовкой и проведением выборов, референдумов (статья 45, пункт 6 статьи 47, статьи 50 - 52, 54, 56 Закона об основных гарантиях избирательных прав, статьи 45 - 53, 55, 56 Федерального закона от 10 января 2003 года N 19-ФЗ \"О выборах Президента Российской Федерации\", статьи 57 - 66, 68, 69 Федерального закона от 22 февраля 2014 года N 20-ФЗ \"О выборах депутатов Государственной Думы Федерального Собрания Российской Федерации\" (далее - Федеральный закон \"О выборах депутатов Государственной Думы Федерального Собрания Российской Федерации\").\nНарушение порядка опубликования (обнародования) материалов, связанных с подготовкой и проведением выборов, референдумов, в том числе допущенное в период избирательной кампании (в период осуществления деятельности по подготовке и проведению выборов со дня официального опубликования (публикации) решения уполномоченного на то должностного лица, государственного органа, органа местного самоуправления о назначении выборов до дня представления избирательной комиссией, организующей выборы, отчета о расходовании средств соответствующего бюджета, выделенных на подготовку и проведение выборов), а также в период кампании референдума (в период осуществления деятельности по подготовке и проведению референдума, осуществляемой со дня регистрации инициативной группы по проведению референдума до дня представления комиссией референдума, организующей референдум, отчета о расходовании средств соответствующего бюджета, выделенных на подготовку и проведение референдума, либо до дня отказа в проведении референдума) в информационно-телекоммуникационных сетях, доступ к которым не ограничен определенным кругом лиц (далее - информационно-телекоммуникационная сеть), влечет административную ответственность по части 1 статьи 5.5 КоАП РФ (подпункты 19 и 34 статьи 2 Закона об основных гарантиях избирательных прав).\nК материалам, связанным с подготовкой и проведением выборов, референдумов, следует относить материалы, посредством которых осуществляется информирование избирателей, участников референдума (в том числе сообщения и материалы о сроках и порядке осуществления избирательных действий, действий, связанных с подготовкой и проведением референдума, о ходе избирательной кампании, кампании референдума, о кандидатах, избирательных объединениях, о проведении предвыборных мероприятий, мероприятий, связанных с референдумом, интервью и передачи с участием кандидатов (информационные материалы), а также материалы, содержащие признаки предвыборной агитации, агитации по вопросам референдума и предназначенные для массового распространения, обнародования в период избирательной кампании, кампании референдума (агитационные материалы) (подпункт 1 статьи 2, пункты 3 - 5 статьи 45 Закона об основных гарантиях избирательных прав)."],
["4","Для целей применения части 1 статьи 5.5 КоАП РФ под нарушением порядка опубликования (обнародования) информационных и (или) агитационных материалов…","","","4. Для целей применения части 1 статьи 5.5 КоАП РФ под нарушением порядка опубликования (обнародования) информационных и (или) агитационных материалов следует понимать несоблюдение установленных законодательством о выборах и референдумах требований и условий к раскрытию и доведению содержащихся в данных материалах сведений до неопределенного круга лиц, обеспечивающих права граждан на получение и распространение информации о выборах и референдумах.\nК числу таких требований и условий относятся, в частности, следующие:\nсодержание информационных материалов, размещаемых в средствах массовой информации или распространяемых иным способом, в том числе в информационно-телекоммуникационной сети, должно быть объективным, достоверным, не должно нарушать равенство кандидатов, избирательных объединений (пункт 2 статьи 45 Закона об основных гарантиях избирательных прав);\nопубликование (обнародование) данных об итогах голосования, о результатах выборов, референдума в день голосования возможно только после момента окончания голосования на территории соответствующего избирательного округа, округа референдума, а при проведении выборов депутатов Государственной Думы Федерального Собрания Российской Федерации - после момента окончания голосования на территории Российской Федерации (пункт 7 статьи 45 Закона об основных гарантиях избирательных прав, часть 6 статьи 58 Федерального закона \"О выборах депутатов Государственной Думы Федерального Собрания Российской Федерации\");\nпри опубликовании (обнародовании) результатов опросов общественного мнения, связанных с выборами и референдумами, должны указываться определенные законом сведения (пункт 2 статьи 46 Закона об основных гарантиях избирательных прав);\nопубликование (обнародование) результатов опросов общественного мнения, связанных с выборами и референдумами, прогнозов результатов выборов и референдумов, иных исследований, связанных с проводимыми выборами и референдумами, возможно только в период, когда это не запрещено (пункт 3 статьи 46 Закона об основных гарантиях избирательных прав);\nсообщения о проведении предвыборных мероприятий, мероприятий, связанных с референдумом, должны даваться в средствах массовой информации, указанных в Законе об основных гарантиях избирательных прав, исключительно отдельным информационным блоком, без комментариев, без оплаты избирательными объединениями, кандидатами, инициативной группой по проведению референдума, иной группой участников референдума; в них не должно отдаваться предпочтение какому бы то ни было кандидату, избирательному объединению, инициативной группе по проведению референдума, иной группе участников референдума, не должна допускаться дискриминация (умаление прав), в том числе по времени освещения их предвыборной деятельности, деятельности, связанной с проведением референдума, объему печатной площади, отведенной для таких сообщений (пункт 5 статьи 45 Закона об основных гарантиях избирательных прав);\nразмещаемые в средствах массовой информации информационные материалы о кандидате, являющемся иностранным агентом, либо о кандидате, аффилированном с иностранным агентом, должны сопровождаться указанием на эти обстоятельства (пункт 5.1 статьи 45 Закона об основных гарантиях избирательных прав);\nэфирное время, печатная площадь для проведения предвыборной агитации, агитации по вопросам референдума должны предоставляться зарегистрированным кандидатам, избирательным объединениям, зарегистрировавшим списки кандидатов, инициативным группам по проведению референдума и иным группам участников референдума на равных условиях, за исключением случаев, установленных законом (пункты 1, 5 статьи 50, пункты 1, 6 - 8 статьи 51, пункты 2, 7 статьи 52 Закона об основных гарантиях избирательных прав);\nсведения о том, что кандидат является иностранным агентом, либо о том, что кандидат является кандидатом, аффилированным с иностранным агентом, или о том, что избирательное объединение выдвинуло на соответствующих выборах такого кандидата (таких кандидатов) (в том числе в составе списка кандидатов), должны быть указаны в размещаемых агитационных материалах такого кандидата, избирательного объединения. Данные сведения (информация) должны соответствовать установленным требованиям, в том числе к объему (занимаемой площади), и представлять собой точное воспроизведение формулировки закона о том, что кандидат является иностранным агентом либо кандидатом, аффилированным с иностранным агентом, что не предполагает изменения этой формулировки и (или) дополнения ее какими-либо оценочными суждениями (пункты 3.1, 9.4 статьи 48, пункт 6 статьи 52 Закона об основных гарантиях избирательных прав);\nпри участии зарегистрированного кандидата, аффилированного с иностранным агентом, в совместном агитационном мероприятии на телевидении или радио его выступление должно предваряться (сопровождаться) информацией о том, что данный кандидат является кандидатом, аффилированным с иностранным агентом (пункт 4.1 статьи 51 Закона об основных гарантиях избирательных прав);\nиспользование в средствах массовой информации в агитационном материале высказывания физического лица, являющегося иностранным агентом, должно предваряться информацией о том, что оно является высказыванием такого физического лица, которая должна отвечать требованиям, установленным к этой информации, в том числе к ее объему (занимаемой площади) (пункт 9.5 статьи 48 Закона об основных гарантиях избирательных прав);\nагитационные материалы, размещаемые редакцией периодического печатного издания, не должны сопровождаться редакционными комментариями в любой форме, а также заголовками и иллюстрациями, не согласованными с соответствующим кандидатом, избирательным объединением, инициативной группой по проведению референдума, иной группой участников референдума (пункт 5 статьи 52 Закона об основных гарантиях избирательных прав);\nразмещение редакцией периодического печатного издания агитационных материалов должно сопровождаться сведениями о том, за счет средств избирательного фонда какого кандидата, избирательного объединения, фонда референдума какой группы, обладающей правом на проведение агитации по вопросам референдума, была произведена оплата соответствующей публикации, либо информацией о безвозмездном характере публикации и о том, кто ее разместил, если агитационные материалы были опубликованы безвозмездно (пункт 6 статьи 52 Закона об основных гарантиях избирательных прав);\nв периодическом печатном издании, учрежденном органом государственной власти, органом местного самоуправления исключительно для опубликования их официальных материалов и сообщений, нормативных правовых и иных актов, не должны публиковаться агитационные материалы, а также редакционные материалы, освещающие деятельность кандидатов, избирательных объединений, инициативной группы по проведению референдума (пункт 6 статьи 47 Закона об основных гарантиях избирательных прав);\nпри предоставлении эфирного времени, печатной площади, услуг по размещению агитационных материалов в сетевых изданиях организацией телерадиовещания, редакцией периодического печатного издания, редакцией сетевого издания должны соблюдаться правила, установленные законом (например, относительно общего объема эфирного времени, которое государственная организация телерадиовещания обязана на равных условиях предоставлять для проведения предвыборной агитации) (пункты 1, 1.3, 4, 6, 9, 12 статьи 50, пункты 1 - 4 статьи 51, пункт 1 статьи 52 Закона об основных гарантиях избирательных прав);\nпредоставление эфирного времени, печатной площади, оказание услуг по размещению агитационных материалов в сетевых изданиях должны производиться в соответствии с договором, заключенным в письменной форме между организацией телерадиовещания, редакцией периодического печатного издания, редакцией сетевого издания и кандидатом, избирательным объединением, представителем инициативной группы по проведению референдума, иной группы участников референдума до предоставления эфирного времени, печатной площади, оказания названных услуг (пункт 11 статьи 50 Закона об основных гарантиях избирательных прав);\nрезервирование и предоставление платного эфирного времени и платной печатной площади для проведения предвыборной агитации, агитации по вопросам референдума на соответствующих выборах, референдуме должно осуществляться государственными и муниципальными организациями телерадиовещания, государственными и муниципальными периодическими печатными изданиями, выходящими не реже одного раза в неделю, с соблюдением установленных законом правил (пункт 6 статьи 51, пункт 2 статьи 52 Закона об основных гарантиях избирательных прав);\nпередача агитационных материалов на каналах организаций телерадиовещания не должна перекрываться трансляцией иных теле- и радиопрограмм, иных агитационных материалов (пункт 9 статьи 51 Закона об основных гарантиях избирательных прав).\nДействия (бездействие), выражающиеся в нарушении приведенных требований и условий законодательства о выборах и референдумах, предъявляемых к порядку опубликования (обнародования) информационных и (или) агитационных материалов, образуют объективную сторону состава административного правонарушения, предусмотренного частью 1 статьи 5.5 КоАП РФ."],
["5","Субъектами административного правонарушения, предусмотренного частью 1 статьи 5.5 КоАП РФ, являются главный редактор, редакция средства массовой…","","","5. Субъектами административного правонарушения, предусмотренного частью 1 статьи 5.5 КоАП РФ, являются главный редактор, редакция средства массовой информации, организация, осуществляющая теле- и (или) радиовещание, иная организация, осуществляющая выпуск или распространение средства массовой информации, а равно любые лица, допустившие нарушения порядка опубликования (обнародования) информационных и (или) агитационных материалов в информационно-телекоммуникационной сети в период избирательной кампании, кампании референдума.\nК средствам массовой информации относятся периодические (выходящие не реже одного раза в год) печатные издания, сетевые издания, телеканалы, радиоканалы, телепрограммы, радиопрограммы, видеопрограммы, кинохроникальные программы, иные формы периодического распространения массовой информации под постоянным наименованием (названием) (например, электронное периодическое издание, информационное агентство), которые подлежат государственной регистрации, за исключением установленных законом случаев освобождения от такой регистрации (статьи 2, 8, 12 Закона Российской Федерации от 27 декабря 1991 года N 2124-I \"О средствах массовой информации\" (далее - Закон о СМИ).\nГлавным редактором признается лицо, возглавляющее редакцию (независимо от наименования должности) и принимающее окончательные решения в отношении производства и выпуска средства массовой информации, в связи с чем он подлежит привлечению к административной ответственности как должностное лицо (абзац десятый статьи 2, часть пятая статьи 19 Закона о СМИ, примечание к статье 2.4 КоАП РФ).\nПривлечение редакции средства массовой информации к административной ответственности зависит от формы организации ее деятельности (абзац девятый статьи 2 Закона о СМИ).\nНапример, если редакция является учреждением, она подлежит привлечению к административной ответственности по части 1 статьи 5.5 КоАП РФ как юридическое лицо (статья 2.10 КоАП РФ).\nВ случае, если в качестве редакции средства массовой информации выступает организация (объединение граждан), функционирующая без государственной регистрации и приобретения прав юридического лица, административную ответственность за совершение редакцией административного правонарушения, предусмотренного указанной нормой, несет главный редактор (примечание к статье 2.4 КоАП РФ, статья 3, часть вторая статьи 41 Федерального закона от 19 мая 1995 года N 82-ФЗ \"Об общественных объединениях\").\nЕсли производство и выпуск средства массовой информации осуществляются единолично физическим лицом, зарегистрированным для осуществления указанной деятельности в качестве индивидуального предпринимателя, такое лицо подлежит привлечению к административной ответственности как должностное лицо, а при отсутствии такой регистрации - как гражданин (примечание к статье 2.4 КоАП РФ).\nК организациям, осуществляющим выпуск средств массовой информации, относятся организации (юридические лица), осуществляющие теле- и (или) радиовещание, а также редакции радио- и телепрограммы, периодического печатного издания (подпункт 46 статьи 2 Закона об основных гарантиях избирательных прав, статья 16.1 Закона о СМИ). При этом выпуск средства массовой информации представляет собой выход в свет (в эфир) продукции средства массовой информации (статьи 26, 27 Закона о СМИ).\nПод организацией, осуществляющей распространение средства массовой информации, понимается юридическое лицо, осуществляющее по договору с редакцией, издателем или на иных законных основаниях распространение средства массовой информации, то есть продажу, подписку, доставку, раздачу периодического печатного издания, аудио- или видеозаписи программы, вещание телеканала, радиоканала (телевизионное вещание, радиовещание), вещание телепрограммы, радиопрограммы в составе соответственно телеканала, радиоканала, демонстрацию кинохроникальной программы, предоставление доступа к сетевому изданию, иные способы распространения (абзацы седьмой и тринадцатый статьи 2 Закона о СМИ).\nСудам следует иметь в виду, что административной ответственности по части 1 статьи 5.5 КоАП РФ подлежат физические и юридические лица, которым адресованы предусмотренные законом требования относительно порядка опубликования (обнародования) информационных и (или) агитационных материалов и которые имеют возможность определять содержание таких материалов и (или) продукции средства массовой информации. В связи с этим к числу субъектов административного правонарушения, предусмотренного указанной нормой, не относятся, например, организации, осуществляющие розничную продажу периодических печатных изданий, выпуск которых произведен иными лицами.\nОбратить внимание судов на то, что физические и юридические лица, не осуществляющие выпуск или распространение средств массовой информации, за распространение, в том числе посредством обнародования, в информационно-телекоммуникационной сети агитационных материалов с нарушением установленных законом требований несут административную ответственность по части 1 статьи 5.12 КоАП РФ."],
["6","Государственные и муниципальные организации, осуществляющие теле- и (или) радиовещание, то есть распространение телеканала или радиоканала в…","","","6. Государственные и муниципальные организации, осуществляющие теле- и (или) радиовещание, то есть распространение телеканала или радиоканала в установленном порядке на основании лицензии на телевизионное вещание, радиовещание, и редакции государственных и муниципальных периодических печатных изданий обязаны безвозмездно предоставлять избирательным комиссиям (комиссиям референдума) эфирное время для информирования избирателей, участников референдума в порядке и в сроки, установленные Законом об основных гарантиях избирательных прав, иными законами, и печатную площадь для опубликования решений комиссий и размещения иной информации (пункт 18 статьи 20, подпункт \"г\" пункта 9 статьи 21, подпункт \"г\" пункта 10 статьи 23, пункты 2, 3 статьи 47 Закона об основных гарантиях избирательных прав).\nНарушение указанного требования влечет административную ответственность названных организаций, редакций, имеющих статус юридического лица, и должностных лиц по части 2 статьи 5.5 КоАП РФ.\nСудам также следует учитывать, что непредставление организациями, осуществляющими теле- и (или) радиовещание, редакциями периодических печатных изданий, сетевых изданий, а также должностными лицами указанных организаций в избирательную комиссию, комиссию референдума сведений и материалов, запрашиваемых комиссией в соответствии с законом, либо представление таких сведений и материалов с нарушением установленного законом срока образует состав административного правонарушения, предусмотренного частью 2 статьи 5.3 КоАП РФ."],
["7","Несоблюдение предусмотренных законодательством о выборах и референдумах порядка и условий осуществления предвыборной агитации, агитации по вопросам…","","","7. Несоблюдение предусмотренных законодательством о выборах и референдумах порядка и условий осуществления предвыборной агитации, агитации по вопросам референдума влечет административную ответственность. Такая ответственность устанавливается, в частности: за нарушение правил проведения предвыборной агитации, агитации по вопросам референдума на каналах организаций, осуществляющих теле- и (или) радиовещание, и в периодических печатных изданиях; за проведение предвыборной агитации, агитации по вопросам референдума вне агитационного периода, либо в местах, где ее проведение запрещено законом, либо лицами, которым участие в проведении предвыборной агитации, агитации по вопросам референдума запрещено законом; за изготовление, распространение или размещение агитационных материалов с нарушением требований законодательства о выборах и референдумах (статьи 5.8, 5.10, 5.11, 5.12, 5.48 КоАП РФ).\nОбратить внимание судов на то, что предвыборная агитация может осуществляться в следующих формах:\nв призывах голосовать за кандидата, кандидатов, список, списки кандидатов либо против него (них);\nв выражении предпочтения какому-либо кандидату, избирательному объединению, в частности в указании на то, за какого кандидата, за какой список кандидатов, за какое избирательное объединение будет голосовать избиратель (за исключением случая опубликования (обнародования) результатов опроса общественного мнения в соответствии с пунктом 2 статьи 46 Закона об основных гарантиях избирательных прав);\nв описании возможных последствий в случае, если тот или иной кандидат будет избран или не будет избран, тот или иной список кандидатов будет допущен или не будет допущен к распределению депутатских мандатов;\nв распространении информации, в которой явно преобладают сведения о каком-либо кандидате (каких-либо кандидатах), избирательном объединении в сочетании с позитивными либо негативными комментариями;\nв распространении информации о деятельности кандидата, не связанной с его профессиональной деятельностью или исполнением им своих служебных (должностных) обязанностей;\nв деятельности, способствующей созданию положительного или отрицательного отношения избирателей к кандидату, избирательному объединению, выдвинувшему кандидата, список кандидатов (подпункт 4 статьи 2, пункт 2 статьи 48 Закона об основных гарантиях избирательных прав).\nПри решении вопроса о привлечении к административной ответственности за нарушения закрепленных законодательством о выборах и референдумах правил осуществления предвыборной агитации подлежит, в частности, установлению то, что лицо, за или против которого проводилась (проводится) предвыборная агитация, выдвинуто в предусмотренном законом порядке в качестве претендента на замещаемую посредством прямых выборов должность в органе государственной власти или органе местного самоуправления либо зарегистрировано соответствующей избирательной комиссией в качестве кандидата. В отсутствие у лица статуса кандидата (выдвинутого или зарегистрированного) распространение материалов о таком лице не может квалифицироваться в качестве предвыборной агитации (подпункт 35 статьи 2 Закона об основных гарантиях избирательных прав)."],
["8","Законодательством о выборах и референдумах закреплены порядок и условия проведения предвыборной агитации, агитации по вопросам референдума в…","","","8. Законодательством о выборах и референдумах закреплены порядок и условия проведения предвыборной агитации, агитации по вопросам референдума в отдельных средствах массовой информации (на каналах организаций телерадиовещания, в периодических печатных изданиях, в сетевых изданиях), несоблюдение которых может повлечь административную ответственность по статье 5.8 КоАП РФ (статьи 48, 50 - 52, 56 Закона об основных гарантиях избирательных прав).\nСубъектами административных правонарушений, предусмотренных статьей 5.8 КоАП РФ, являются:\nграждане (в частности, кандидат, член или уполномоченный представитель инициативной группы по проведению референдума, иных групп участников референдума, физическое лицо, уполномоченное выступать от имени кандидата, избирательного объединения (например, доверенное лицо), или не зарегистрированное в качестве индивидуального предпринимателя физическое лицо, привлеченное к проведению предвыборной агитации);\nдолжностные лица (например, лицо, замещающее государственную должность или выборную муниципальную должность, должностное лицо избирательного объединения, в том числе не являющегося юридическим лицом);\nюридические лица (избирательные объединения, имеющие статус юридического лица, иные юридические лица, включая привлеченных для проведения предвыборной агитации)."],
["9","Объективная сторона состава административного правонарушения, предусмотренного статьей 5.8 КоАП РФ, может выражаться, в частности, в несоблюдении…","","","9. Объективная сторона состава административного правонарушения, предусмотренного статьей 5.8 КоАП РФ, может выражаться, в частности, в несоблюдении следующих требований о запрете:\nиспользовать зарегистрированным кандидатом, избирательным объединением предоставленные им эфирное время, печатную площадь для проведения предвыборной агитации за других зарегистрированных кандидатов, за другие избирательные объединения (за исключением случаев проведения на тех же выборах предвыборной агитации зарегистрированным кандидатом за выдвинувшее его избирательное объединение, а также за других кандидатов, выдвинутых этим избирательным объединением, либо избирательным объединением, выдвинувшим кандидатов, список кандидатов, за любого выдвинутого им кандидата) (пункт 2 статьи 50 Закона об основных гарантиях избирательных прав);\nиспользовать зарегистрированным кандидатом, избирательным объединением эфирное время на каналах организаций, осуществляющих телевещание, предоставленное им для размещения агитационных материалов, в целях: распространения призывов голосовать против кандидата (кандидатов), списка (списков) кандидатов; описания возможных негативных последствий в случае, если тот или иной кандидат будет избран, тот или иной список кандидатов будет допущен к распределению депутатских мандатов; распространения информации, в которой явно преобладают сведения о каком-либо кандидате (каких-либо кандидатах), избирательном объединении в сочетании с негативными комментариями; распространения информации, способствующей созданию отрицательного отношения избирателей к кандидату, избирательному объединению, выдвинувшему кандидата, список кандидатов (пункт 5.2 статьи 56 Закона об основных гарантиях избирательных прав);\nиспользовать лицу, замещающему государственную или выборную муниципальную должность, преимущества своего должностного или служебного положения при проведении агитации по вопросам референдума (пункт 8.1 статьи 48 Закона об основных гарантиях избирательных прав);\nпризывать к совершению деяний, определяемых в статье 1 Федерального закона от 25 июля 2002 года N 114-ФЗ \"О противодействии экстремистской деятельности\" (далее - Закон о противодействии экстремистской деятельности) как экстремистская деятельность, либо иным способом побуждать к таким деяниям, а также обосновывать или оправдывать экстремизм кандидатам и их доверенным лицам, представителям и доверенным лицам избирательных объединений, представителям инициативной и иных групп по проведению референдума, лицам, замещающим государственные должности или выборные муниципальные должности, в ходе выступлений в средствах массовой информации (в том числе размещаемых в информационно-телекоммуникационных сетях, включая сеть \"Интернет\") (пункт 1 статьи 56 Закона об основных гарантиях избирательных прав);\nзлоупотреблять свободой массовой информации в иных формах, в частности предусмотренных в статье 4 Закона о СМИ (пункт 1.1 статьи 56 Закона об основных гарантиях избирательных прав).\nВ то же время следует учитывать, что неучастие избирательного объединения, зарегистрированного кандидата, инициативной группы по проведению референдума в совместном агитационном мероприятии на телевидении или радио не является основанием для привлечения к административной ответственности (пункты 4 - 5 статьи 51 Закона об основных гарантиях избирательных прав)."],
["10","Предвыборная агитация, агитация по вопросам референдума вне установленного законодательством о выборах и референдумах периода, в течение которого…","","","10. Предвыборная агитация, агитация по вопросам референдума вне установленного законодательством о выборах и референдумах периода, в течение которого разрешается проводить такую агитацию (агитационного периода), либо агитация в местах, где ее проведение указанным законодательством запрещено, образует объективную сторону составов административных правонарушений, предусмотренных статьей 5.10 КоАП РФ.\nК числу мест, в которых законодательством о выборах и референдумах запрещено проводить предвыборную агитацию, агитацию по вопросам референдума, относятся, в частности, воинские части, военные организации и учреждения (за исключением случаев, когда единственное здание или помещение, пригодное для проведения агитационного публичного мероприятия в форме собрания, находится в расположении воинской части либо в военной организации или учреждении) (пункт 7 статьи 53 Закона об основных гарантиях избирательных прав)."],
["11","Для правильного разрешения дел об административных правонарушениях, объективная сторона которых выражается в осуществлении предвыборной агитации,…","","","11. Для правильного разрешения дел об административных правонарушениях, объективная сторона которых выражается в осуществлении предвыборной агитации, агитации по вопросам референдума вне агитационного периода, установленного законодательством о выборах и референдумах, судам необходимо учитывать следующее:\nагитационный период для избирательного объединения начинается со дня принятия им решения о выдвижении кандидата, кандидатов, списка кандидатов;\nагитационный период для кандидата, выдвинутого в составе списка кандидатов, начинается со дня представления в соответствующую избирательную комиссию списка кандидатов;\nагитационный период для кандидата, выдвинутого непосредственно, начинается со дня представления кандидатом в избирательную комиссию заявления о согласии баллотироваться, а в случае, предусмотренном пунктом 14.3 статьи 35 Закона об основных гарантиях избирательных прав, - со дня представления в избирательную комиссию документов, предусмотренных в указанном пункте (пункт 1 статьи 49 Закона об основных гарантиях избирательных прав).\nАгитационный период при проведении референдума начинается со дня регистрации инициативной группы по проведению референдума (пункт 1 статьи 49 Закона об основных гарантиях избирательных прав).\nГраждане вправе проводить предвыборную агитацию, агитацию по вопросам референдума по собственной инициативе с начала агитационного периода, определенного для того субъекта, за или против которого они агитируют, либо с начала агитационного периода при проведении референдума.\nАгитационный период заканчивается в ноль часов по местному времени дня, предшествующего дню голосования, а в случае принятия решения о голосовании в течение нескольких дней подряд - в ноль часов по местному времени первого дня голосования (пункт 1 статьи 49 Закона об основных гарантиях избирательных прав).\nТакже на определение периода, в рамках которого может проводиться предвыборная агитация, агитация по вопросам референдума, влияет выбранный метод агитации.\nТак, период проведения предвыборной агитации, агитации по вопросам референдума на каналах организаций телерадиовещания, в периодических печатных изданиях и в сетевых изданиях начинается за 28 дней до дня голосования и прекращается в ноль часов по местному времени дня, предшествующего дню голосования, а в случае принятия решения о голосовании в течение нескольких дней подряд - в ноль часов по местному времени первого дня голосования (пункт 2 статьи 49 Закона об основных гарантиях избирательных прав).\nНапример, если день голосования назначен на 10 сентября и принято решение о проведении голосования в течение трех дней подряд, временем начала периода проведения предвыборной агитации на каналах организаций телерадиовещания, в периодических печатных изданиях и в сетевых изданиях будет являться ноль часов 12 августа, а временем его окончания - ноль часов 8 сентября."],
["12","Осуществление предвыборной агитации, агитации по вопросам референдума вне агитационного периода, установленного законодательством о выборах и…","","","12. Осуществление предвыборной агитации, агитации по вопросам референдума вне агитационного периода, установленного законодательством о выборах и референдумах, в ходе публичного мероприятия, которое организовано или проводится с нарушением требований законодательства Российской Федерации, подлежит квалификации как самостоятельное административное правонарушение по статье 5.10 КоАП РФ и соответствующей части статьи 20.2 Кодекса.\nВ связи с тем, что рассмотрение дел об административных правонарушениях, предусмотренных статьей 5.10 КоАП РФ, по общему правилу отнесено к компетенции мировых судей, а дела об административных правонарушениях, предусмотренных статьей 20.2 КоАП РФ, подсудны судьям районных судов, административные наказания за данные административные правонарушения назначаются в соответствии с частью 1 статьи 4.4 КоАП РФ, в том числе если они совершены в результате одного действия (бездействия) (часть 1, абзацы третий и шестой части 3 статьи 23.1 КоАП РФ)."],
["13","Привлечению к административной ответственности по статье 5.10 КоАП РФ подлежат:","","","13. Привлечению к административной ответственности по статье 5.10 КоАП РФ подлежат:\nграждане (в частности, кандидат, уполномоченный представитель избирательного объединения, член или уполномоченный представитель инициативной группы по проведению референдума, иных групп участников референдума, физическое лицо, уполномоченное выступать от имени кандидата, избирательного объединения (например, доверенное лицо), или физическое лицо, привлеченное к проведению предвыборной агитации либо осуществляющее ее самостоятельно по собственной инициативе);\nдолжностные лица (например, должностное лицо избирательного объединения, в том числе не являющегося юридическим лицом, должностное лицо организации, осуществляющей выпуск средств массовой информации, индивидуальный предприниматель, привлеченный для проведения предвыборной агитации);\nюридические лица (имеющие статус юридического лица избирательные объединения, зарегистрированные в качестве юридического лица организации, осуществляющие выпуск средств массовой информации, иные юридические лица, в том числе привлеченные для проведения предвыборной агитации)."],
["14","Законодательством о выборах и референдумах определены субъекты, которым запрещается проводить предвыборную агитацию, агитацию по вопросам…","","","14. Законодательством о выборах и референдумах определены субъекты, которым запрещается проводить предвыборную агитацию, агитацию по вопросам референдума, выпускать и распространять любые агитационные материалы.\nЗа проведение предвыборной агитации, агитации по вопросам референдума лица, которым участие в ее проведении запрещено законом, подлежат привлечению к административной ответственности по статье 5.11 КоАП РФ.\nК числу таких лиц относятся:\nфедеральные органы государственной власти, органы государственной власти субъектов Российской Федерации, органы публичной власти федеральной территории, иные государственные органы, органы местного самоуправления;\nлица, замещающие государственные или выборные муниципальные должности, государственные и муниципальные служащие, лица, являющиеся членами органов управления организаций независимо от формы собственности (в организациях, высшим органом управления которых является собрание, - членами органов, осуществляющих руководство деятельностью этих организаций), за исключением политических партий, при исполнении ими своих должностных или служебных обязанностей (кроме случая, предусмотренного пунктом 8.1 статьи 48 Закона об основных гарантиях избирательных прав) и (или) с использованием преимуществ своего должностного или служебного положения (указание в агитационном материале должности такого лица не является нарушением данного запрета);\nлица, замещающие государственные или выборные муниципальные должности, при проведении предвыборной агитации на каналах организаций телерадиовещания и в периодических печатных изданиях, за исключением случаев, если указанные лица зарегистрированы в качестве кандидатов в депутаты или на выборные должности;\nвоинские части, военные учреждения и организации;\nблаготворительные и религиозные организации, учрежденные ими организации, а также члены и участники религиозных объединений при совершении обрядов и церемоний;\nизбирательные комиссии, комиссии референдума, члены комиссий с правом решающего голоса на территории любого избирательного округа, округа референдума;\nиностранные граждане (за исключением случая, предусмотренного пунктом 10 статьи 4 Закона об основных гарантиях избирательных прав), лица без гражданства, иностранные юридические лица;\nмеждународные организации и международные общественные движения;\nпредставители организаций, осуществляющих выпуск средств массовой информации, и представители редакций сетевых изданий при осуществлении ими профессиональной деятельности;\nлица, в отношении которых решением суда установлен факт нарушения ограничений, предусмотренных пунктом 1 статьи 56 Закона об основных гарантиях избирательных прав, в период проводимой избирательной кампании, кампании референдума (пункты 7, 8 статьи 48 Закона об основных гарантиях избирательных прав).\nС учетом того, что иностранные агенты не могут осуществлять деятельность, способствующую либо препятствующую выдвижению кандидатов, списков кандидатов, избранию зарегистрированных кандидатов, выдвижению инициативы проведения референдума и проведению референдума, достижению определенного результата на выборах, референдуме, а также в иных формах участвовать в избирательных кампаниях, кампаниях референдума, такие лица не вправе проводить предвыборную агитацию, агитацию по вопросам референдума (за исключением случаев, когда лицо, являющееся иностранным агентом, выдвинуто в качестве кандидата) (пункт 3.4 статьи 33, пункт 1.7, подпункт \"а.3\" пункта 24 статьи 38, пункт 5.1 статьи 45, пункт 9.4 статьи 48, пункт 2 статьи 54 Закона об основных гарантиях избирательных прав, часть 6 статьи 11 Федерального закона от 14 июля 2022 года N 255-ФЗ \"О контроле за деятельностью лиц, находящихся под иностранным влиянием\" (далее - Закон о контроле за деятельностью лиц, находящихся под иностранным влиянием)."],
["15","Обратить внимание судов, что к числу представителей организаций, осуществляющих выпуск средств массовой информации, и представителей редакций сетевых…","","","15. Обратить внимание судов, что к числу представителей организаций, осуществляющих выпуск средств массовой информации, и представителей редакций сетевых изданий относятся главный редактор, журналист, лица, на которых распространяется профессиональный статус журналиста, а также иные лица, имеющие редакционное удостоверение или иной документ, удостоверяющий его полномочия представителя организации, осуществляющей выпуск средств массовой информации, представителя редакции сетевого издания (подпункт 52 статьи 2 Закона об основных гарантиях избирательных прав, статьи 2, 19, 52 Закона о СМИ).\nПри привлечении названных лиц к административной ответственности по статье 5.11 КоАП РФ следует учитывать особенности признания их действий предвыборной агитацией в зависимости от формы ее проведения.\nТак, предвыборной агитацией являются совершаемые однократно при осуществлении представителями организаций, осуществляющих выпуск средств массовой информации, и представителями редакций сетевых изданий профессиональной деятельности призывы голосовать за кандидата, кандидатов, список, списки кандидатов либо против него (них), если эти действия совершены с целью побудить избирателей голосовать за кандидата, кандидатов, список, списки кандидатов или против него (них).\nПри этом иные действия указанных лиц признаются предвыборной агитацией только в случае их совершения с целью побудить избирателей голосовать за кандидата, кандидатов, список, списки кандидатов или против него (них) неоднократно (то есть два и более раза в рамках одной избирательной кампании). К таким действиям относятся: выражение предпочтения какому-либо кандидату, избирательному объединению; описание возможных последствий в случае, если тот или иной кандидат будет избран или не будет избран, тот или иной список кандидатов будет допущен или не будет допущен к распределению депутатских мандатов; распространение информации, в которой явно преобладают сведения о каком-либо кандидате (каких-либо кандидатах), избирательном объединении в сочетании с позитивными либо негативными комментариями; распространение информации о деятельности кандидата, не связанной с его профессиональной деятельностью или исполнением им своих служебных (должностных) обязанностей; деятельность, способствующая созданию положительного или отрицательного отношения избирателей к кандидату, избирательному объединению, выдвинувшему кандидата, список кандидатов (пункт 2.1 статьи 48 Закона об основных гарантиях избирательных прав)."],
["16","Объективную сторону состава административного правонарушения, предусмотренного статьей 5.11 КоАП РФ, также образует привлечение к проведению…","","","16. Объективную сторону состава административного правонарушения, предусмотренного статьей 5.11 КоАП РФ, также образует привлечение к проведению предвыборной агитации, агитации по вопросам референдума лиц, которые не достигли на день (последний день) голосования возраста 18 лет, в формах и методами, которые запрещены законом.\nПри рассмотрении дел об административных правонарушениях, предусмотренных статьей 5.11 КоАП РФ, судам необходимо исходить из того, что действующее законодательство о выборах и референдумах содержит запрет привлекать к участию в проведении предвыборной агитации, агитации по вопросам референдума во всех формах и с использованием любых методов лиц, не достигших на день (последний день) голосования возраста 18 лет, в том числе использовать изображения и высказывания таких лиц в агитационных материалах (пункт 6 статьи 48 Закона об основных гарантиях избирательных прав).\nПривлечение к проведению предвыборной агитации, агитации по вопросам референдума несовершеннолетних может выражаться в предоставлении возможности как для их непосредственного участия в предвыборной агитации (например, путем осуществления такими несовершеннолетними лицами призывов голосовать за или против кандидата, избирательного объединения, путем распространения или демонстрации агитационных материалов), так и для участия в действиях, обеспечивающих проведение агитации (например, посредством личного участия в изготовлении агитационных материалов)."],
["17","Изготовление и (или) распространение, в том числе в информационно-телекоммуникационной сети, печатных, аудиовизуальных и иных видов агитационных…","","","17. Изготовление и (или) распространение, в том числе в информационно-телекоммуникационной сети, печатных, аудиовизуальных и иных видов агитационных материалов с нарушением требований, установленных законодательством о выборах и референдумах, в период подготовки и проведения выборов, референдума влечет административную ответственность по части 1 статьи 5.12 КоАП РФ (подпункты 1 и 19 статьи 2 Закона об основных гарантиях избирательных прав).\nДля целей применения части 1 статьи 5.12 КоАП РФ под изготовлением агитационных материалов следует понимать как заказ на созданные материалы, так и выполнение работ, оказание услуг по их созданию (подготовке), а под распространением - действия, направленные на получение (включая возможность получения) агитационных материалов неопределенным кругом лиц или их передачу неопределенному кругу лиц.\nВыполнять работы или оказывать услуги по изготовлению печатных агитационных материалов вправе исключительно организации, индивидуальные предприниматели, опубликовавшие сведения о размере (в валюте Российской Федерации) и других условиях оплаты своих работ или услуг не позднее чем через 30 дней со дня официального опубликования (публикации) решения о назначении выборов, регистрации инициативной группы по проведению референдума и в тот же срок представившие их в определяемую законом избирательную комиссию, комиссию референдума вместе со сведениями, содержащими наименование, юридический адрес и идентификационный номер налогоплательщика организации (фамилию, имя, отчество индивидуального предпринимателя, наименование субъекта Российской Федерации, района, города, иного населенного пункта, где находится место его жительства) (далее - данные, позволяющие идентифицировать изготовителя печатных агитационных материалов) (пункт 1.1 статьи 54 Закона об основных гарантиях избирательных прав).\nРаботы или услуги по изготовлению любых агитационных материалов не могут оказываться лицами, являющимися иностранными агентами (часть 6 статьи 11 Закона о контроле за деятельностью лиц, находящихся под иностранным влиянием)."],
["18","Организации, индивидуальные предприниматели при изготовлении печатных агитационных материалов обязаны обеспечить кандидатам, избирательным…","","","18. Организации, индивидуальные предприниматели при изготовлении печатных агитационных материалов обязаны обеспечить кандидатам, избирательным объединениям, выдвинувшим списки кандидатов, инициативной группе по проведению референдума, иным группам участников референдума равные условия оплаты изготовления этих материалов (пункт 1.1 статьи 54 Закона об основных гарантиях избирательных прав).\nНевыполнение приведенных требований влечет административную ответственность указанных лиц по части 1 статьи 5.12 КоАП РФ."],
["19","Кандидатам, их уполномоченным или доверенным лицам, избирательным объединениям, членам и уполномоченным представителям избирательных объединений,…","","","19. Кандидатам, их уполномоченным или доверенным лицам, избирательным объединениям, членам и уполномоченным представителям избирательных объединений, инициативным группам по проведению референдума, иным группам участников референдума, членам и уполномоченным представителям данных групп, а равно иным лицам как заказчикам агитационных материалов адресованы в том числе следующие требования:\nизготавливать агитационные материалы исключительно на территории Российской Федерации (пункт 1 статьи 54 Закона об основных гарантиях избирательных прав);\nне использовать лицам, замещающим государственные или выборные муниципальные должности, преимущества своего должностного или служебного положения при выпуске агитационных материалов по вопросам референдума (пункт 8.1 статьи 48 Закона об основных гарантиях избирательных прав);\nне использовать в агитационных материалах высказывания физического лица, не имеющего права проводить предвыборную агитацию, агитацию по вопросам референдума, об избирательном объединении, выдвинувшем список кандидатов, кандидатов по одномандатным (многомандатным) избирательным округам, о кандидате (кандидатах), по вопросу референдума (например, запрещается использование высказываний лица, замещающего государственную или выборную муниципальную должность, при исполнении должностных (служебных) обязанностей) (пункт 8.2 статьи 48, пункт 5 статьи 54 Закона об основных гарантиях избирательных прав);\nиспользовать высказывания физического лица о кандидате, об избирательном объединении, по вопросу референдума (либо изображения физического лица в агитационных материалах при проведении референдума) только при наличии письменного согласия данного физического лица и с представлением документа, подтверждающего такое согласие, в избирательную комиссию, комиссию референдума вместе с экземплярами агитационных материалов, если иное не установлено законом (пункты 9, 9.3 статьи 48 Закона об основных гарантиях избирательных прав);\nпредставлять в случае использования в агитационном материале высказываний физического лица, являющегося иностранным агентом, в избирательную комиссию информацию о том, какое высказывание какого физического лица, являющегося иностранным агентом, использовано в агитационном материале (пункт 9.5 статьи 48, пункты 2, 5 статьи 54 Закона об основных гарантиях избирательных прав)."],
["20","Привлечению к административной ответственности по части 1 статьи 5.12 КоАП РФ подлежат также заказчики и лица, выполнившие работы, оказавшие услуги…","","","20. Привлечению к административной ответственности по части 1 статьи 5.12 КоАП РФ подлежат также заказчики и лица, выполнившие работы, оказавшие услуги по созданию (подготовке) агитационных материалов всех видов, в частности, со следующими нарушениями:\nбез предварительной оплаты из средств соответствующего избирательного фонда, фонда референдума (пункт 5 статьи 54 Закона об основных гарантиях избирательных прав);\nбез указания в печатных и аудиовизуальных, в том числе предназначенных для размещения в информационно-телекоммуникационной сети, агитационных материалах наименования, юридического адреса и идентификационного номера налогоплательщика организации (фамилии, имени, отчества лица и наименования субъекта Российской Федерации, района, города, иного населенного пункта, где находится место его жительства), изготовившей (изготовившего) данные материалы, наименования организации (фамилии, имени, отчества лица), заказавшей (заказавшего) их, а также информации о тираже, дате изготовления этих материалов и об оплате их изготовления из средств соответствующего избирательного фонда, фонда референдума (пункт 2 статьи 54 Закона об основных гарантиях избирательных прав);\nсодержащих признаки экстремизма, призывы к совершению деяний, определяемых в статье 1 Закона о противодействии экстремистской деятельности как экстремистская деятельность, либо иным способом побуждающих к таким деяниям, а также обосновывающих или оправдывающих экстремизм (пункт 1 статьи 56 Закона об основных гарантиях избирательных прав);\nсодержащих коммерческую рекламу (пункт 5.1 статьи 56 Закона об основных гарантиях избирательных прав);\nявляющихся подложными агитационными материалами (пункты 8 и 9 статьи 56 Закона об основных гарантиях избирательных прав);\nс использованием вводящих в заблуждение и выдаваемых за достоверные недостоверных изображений, аудио- и аудиовизуальной информации, в том числе созданных с помощью компьютерных технологий (пункт 1.1 статьи 56 Закона об основных гарантиях избирательных прав);\nс использованием изображений любого физического лица, в том числе умершего (фотографий, видеозаписей или произведений изобразительного искусства, изображений, созданных с использованием компьютерных технологий), за исключением случаев использования избирательным объединением изображений выдвинутых им на соответствующих выборах кандидатов (в том числе в составе списка кандидатов), включая кандидатов среди неопределенного круга лиц, а также использования кандидатом своих изображений, в том числе среди неопределенного круга лиц (пункт 9.1 статьи 48, пункт 5 статьи 54 Закона об основных гарантиях избирательных прав);\nс использованием изображений и высказываний лиц, не достигших на день (последний день) голосования возраста 18 лет, в том числе изображений кандидата в несовершеннолетнем возрасте (пункт 6 статьи 48, пункт 5 статьи 54 Закона об основных гарантиях избирательных прав);\nпри отсутствии в агитационных материалах кандидата, являющегося иностранным агентом, кандидата, аффилированного с иностранным агентом, избирательного объединения, выдвинувшего на соответствующих выборах (в том числе в составе списка кандидатов) такого кандидата, указания на то, что данный кандидат является иностранным агентом или кандидатом, аффилированным с иностранным агентом, что избирательным объединением выдвинут (в том числе в составе списка кандидатов) такой кандидат (пункт 9.4 статьи 48, пункт 6 статьи 52, пункты 2 и 5 статьи 54 Закона об основных гарантиях избирательных прав);\nс использованием высказываний физического лица, являющегося иностранным агентом, без предварительного указания на то, что такое лицо является иностранным агентом (пункт 9.5 статьи 48, пункт 6 статьи 52, пункты 2 и 5 статьи 54 Закона об основных гарантиях избирательных прав);\nс несоблюдением установленных требований к маркировке агитационных материалов (в частности, к объему занимаемой площади) кандидата, являющегося иностранным агентом, кандидата, аффилированного с иностранным агентом, избирательного объединения, выдвинувшего на соответствующих выборах (в том числе в составе списка кандидатов) такого кандидата, либо агитационных материалов, содержащих высказывания физического лица, являющегося иностранным агентом (пункты 9.4, 9.5 статьи 48 Закона об основных гарантиях избирательных прав)."],
["21","В случае, если заказчиком агитационных материалов является лицо, которому запрещено проведение предвыборной агитации, например иностранный агент (за…","","","21. В случае, если заказчиком агитационных материалов является лицо, которому запрещено проведение предвыборной агитации, например иностранный агент (за исключением случаев, когда лицо, являющееся иностранным агентом, выдвинуто в качестве кандидата), привлечению к административной ответственности по части 1 статьи 5.12 КоАП РФ подлежат как указанное лицо, так и лицо, выполнившее работы или оказавшее услуги по изготовлению агитационных материалов по его заказу (пункт 3.4 статьи 33, пункт 1.7, подпункт \"а.3\" пункта 24 статьи 38, пункт 7 статьи 48, пункт 5 статьи 54 Закона об основных гарантиях избирательных прав, часть 6 статьи 11 Закона о контроле за деятельностью лиц, находящихся под иностранным влиянием)."],
["22","За нарушение запрета на изготовление печатных агитационных материалов по договору с физическими лицами, не являющимися индивидуальными…","","","22. За нарушение запрета на изготовление печатных агитационных материалов по договору с физическими лицами, не являющимися индивидуальными предпринимателями, либо с лицами, являющимися иностранными агентами, либо в организациях или у индивидуальных предпринимателей, не опубликовавших сведения о размере (в валюте Российской Федерации) и других условиях оплаты своих работ или услуг по изготовлению печатных агитационных материалов в установленный срок и (или) не представивших их в тот же срок в соответствующую избирательную комиссию, комиссию референдума вместе с данными, позволяющими идентифицировать изготовителя печатных агитационных материалов, к административной ответственности по части 1 статьи 5.12 КоАП РФ подлежат привлечению как заказчики данных материалов, так и лица, выполнившие работы, оказавшие услуги по созданию (подготовке) агитационных материалов (пункты 1.1, 5 статьи 54 Закона об основных гарантиях избирательных прав, часть 6 статьи 11 Закона о контроле за деятельностью лиц, находящихся под иностранным влиянием)."],
["23","Распространение агитационных материалов с нарушением какого-либо из установленных законодательством о выборах и референдумах требований,…","","","23. Распространение агитационных материалов с нарушением какого-либо из установленных законодательством о выборах и референдумах требований, предъявляемых к изготовлению агитационных материалов, включая требования к агитационным материалам определенных видов, влечет административную ответственность виновного лица по части 1 статьи 5.12 КоАП РФ (пункты 5, 6, 7, 8.2, 9, 9.1, 9.3, 9.4, 9.5 статьи 48, пункты 2, 5, 6 статьи 54, пункты 1, 1.1, 5.1, 8 статьи 56 Закона об основных гарантиях избирательных прав).\nКроме того, нарушения порядка распространения агитационных материалов, влекущие административную ответственность виновных лиц по части 1 статьи 5.12 КоАП РФ, могут выражаться:\nв распространении печатных и аудиовизуальных агитационных материалов до представления в соответствующую избирательную комиссию их экземпляра или копии либо в распространении иных агитационных материалов до представления в соответствующую избирательную комиссию их фотографии, экземпляра или копии, а в случаях, предусмотренных законом, без представления электронных образов агитационных материалов в машиночитаемом виде, вместе со сведениями о месте нахождения (об адресе места жительства) организации (лица), изготовившей и заказавшей (изготовившего и заказавшего) эти материалы, и копией документа об оплате изготовления предвыборных агитационных материалов из соответствующего избирательного фонда (пункты 3 и 6 статьи 54 Закона об основных гарантиях избирательных прав);\nв распространении агитационных материалов на каналах организаций, осуществляющих телерадиовещание, в периодических печатных изданиях, в случае если после направления (передачи) агитационного материала в указанную организацию, редакцию периодического печатного издания и до начала его распространения зарегистрированным кандидатом, избирательным объединением в соответствующую избирательную комиссию не была представлена копия такого агитационного материала вместе с информацией о том, изображение какого кандидата (каких кандидатов) использовано в соответствующем агитационном материале (в случае использования изображений кандидата (кандидатов) в агитационном материале) (пункт 11.1 статьи 50 Закона об основных гарантиях избирательных прав);\nв размещении агитационных материалов на информационных ресурсах, в том числе сайтах в сети \"Интернет\", доступ к которым ограничен федеральным органом исполнительной власти, осуществляющим функции по контролю и надзору в сфере средств массовой информации, массовых коммуникаций, информационных технологий и связи, в соответствии с Федеральным законом от 27 июля 2006 года N 149-ФЗ \"Об информации, информационных технологиях и о защите информации\" (пункт 1.2 статьи 56 Закона об основных гарантиях избирательных прав)."],
["24","Субъектами административной ответственности по части 1 статьи 5.12 КоАП РФ могут являться:","","","24. Субъектами административной ответственности по части 1 статьи 5.12 КоАП РФ могут являться:\nграждане (в частности, кандидат, член или уполномоченный представитель инициативной группы по проведению референдума, иных групп участников референдума, физическое лицо, уполномоченное выступать от имени кандидата, избирательного объединения (например, доверенное лицо), или физическое лицо, привлеченное к проведению предвыборной агитации (в том числе на основании договора (соглашения) о выполнении определенных работ (об оказании услуг) либо осуществляющее ее самостоятельно по собственной инициативе, владелец сайта или страницы сайта в сети \"Интернет\" (включая страницу в социальной сети, страницу сайта (канал) сервиса обмена мгновенными сообщениями), на которых размещается общедоступная информация, доступ к которой предоставляется для неопределенного круга лиц);\nдолжностные лица (например, должностное лицо избирательного объединения, в том числе не являющегося юридическим лицом, индивидуальный предприниматель, привлеченный для проведения предвыборной агитации (в том числе на основании договора (соглашения) о выполнении определенных работ (об оказании услуг);\nюридические лица (имеющие статус юридического лица избирательные объединения, юридические лица, привлеченные для проведения предвыборной агитации (в том числе на основании договора (соглашения) о выполнении определенных работ (об оказании услуг)."],
["25","Судам при рассмотрении дел об административных правонарушениях, предусмотренных частью 1 статьи 5.12 КоАП РФ, следует устанавливать вину лица,…","","","25. Судам при рассмотрении дел об административных правонарушениях, предусмотренных частью 1 статьи 5.12 КоАП РФ, следует устанавливать вину лица, привлекаемого к административной ответственности, в несоблюдении установленных законом требований к изготовлению и (или) распространению агитационных материалов.\nНапример, распространение таких печатных агитационных материалов почтальоном по поручению работодателя при осуществлении им трудовой функции не образует состава названного административного правонарушения. К административной ответственности в указанном случае может быть привлечен работодатель либо иное уполномоченное лицо организации, по поручению которого агитационные материалы распространены с нарушением требований законодательства о выборах и референдумах."],
["26","Граждане, не являющиеся кандидатами и не уполномоченные в установленном законом порядке выступать от имени кандидатов, избирательных объединений, не…","","","26. Граждане, не являющиеся кандидатами и не уполномоченные в установленном законом порядке выступать от имени кандидатов, избирательных объединений, не вправе проводить предвыборную агитацию в таких формах и такими методами, которые требуют финансовых затрат и не оплачены из избирательного фонда (пункт 2 статьи 39, пункт 5 статьи 48, пункт 5 статьи 59 Закона об основных гарантиях избирательных прав). Изготовление и (или) распространение агитационных материалов с нарушением данного запрета влечет административную ответственность по части 1 статьи 5.12 КоАП РФ.\nДобровольное на безвозмездной основе личное выполнение гражданином работ, оказание им услуг по подготовке и проведению выборов, референдума без привлечения третьих лиц (например, оказание помощи кандидату в распространении агитационных материалов, изготовленных за счет средств избирательного фонда и с соблюдением иных установленных законом требований) не образуют состава указанного административного правонарушения (пункт 5 статьи 59 Закона об основных гарантиях избирательных прав)."],
["27","Обратить внимание судов на то, что наличие в агитационных материалах, в выступлениях на публичных мероприятиях, в средствах массовой информации…","","","27. Обратить внимание судов на то, что наличие в агитационных материалах, в выступлениях на публичных мероприятиях, в средствах массовой информации признаков экстремизма, призывов к совершению деяний, определяемых в статье 1 Закона о противодействии экстремистской деятельности как экстремистская деятельность, побуждения к таким деяниям, а также обоснования или оправдания экстремизма влечет административную ответственность по статье 5.8 КоАП РФ (в случае, если такое нарушение допущено при проведении агитации в средствах массовой информации) либо по части 1 статьи 5.12 КоАП РФ (в случае изготовления и (или) распространения агитационных материалов с такими нарушениями), а также может повлечь административную ответственность по иным статьям Кодекса (например, по части 2 или 6 статьи 13.15, статьям 13.37, 20.3, 20.3.1, 20.3.2, 20.29 КоАП РФ)."],
["28","Законодательство о выборах и референдумах содержит запрет размещать (в том числе путем вывешивания, расклеивания) агитационные материалы на…","","","28. Законодательство о выборах и референдумах содержит запрет размещать (в том числе путем вывешивания, расклеивания) агитационные материалы на памятниках, обелисках, зданиях, сооружениях и в помещениях, имеющих историческую, культурную или архитектурную ценность, а также в зданиях, в которых размещены избирательные комиссии, помещения для голосования, и на расстоянии менее 50 метров от входа в них (пункт 10 статьи 54 Закона об основных гарантиях избирательных прав).\nНарушение данного требования влечет административную ответственность по части 2 статьи 5.12 КоАП РФ."],
["29","Объективную сторону состава административного правонарушения, предусмотренного частью 2 статьи 5.12 КоАП РФ, образует также размещение печатных…","","","29. Объективную сторону состава административного правонарушения, предусмотренного частью 2 статьи 5.12 КоАП РФ, образует также размещение печатных агитационных материалов в помещениях, зданиях, на сооружениях и иных объектах без согласия либо с нарушением условий собственников или владельцев указанных объектов (например, несоблюдение условия о размещении агитационного материала на указанном собственником (владельцем) объекта месте либо превышение согласованного количества размещаемых агитационных материалов) (пункт 8 статьи 54 Закона об основных гарантиях избирательных прав).\nСудам следует иметь в виду, что согласия собственника здания на размещение агитационных материалов не требуется в случае их размещения с согласия владельца рекламной конструкции, установленной на здании и эксплуатируемой по договору между таким владельцем и собственником (или лицом, уполномоченным собственником) здания, на котором она расположена. В этом случае к административной ответственности за нарушение требований к распространению агитационных материалов может быть привлечен владелец рекламной конструкции.\nСогласия собственника или владельца объекта также не требуется в случае размещения печатных агитационных материалов в специальных местах для размещения печатных агитационных материалов на территории каждого избирательного участка, участка референдума, выделенных органами местного самоуправления по предложению соответствующей избирательной комиссии (пункт 7 статьи 54 Закона об основных гарантиях избирательных прав).\nНаличие указанных специальных мест не исключает возможности размещения печатных агитационных материалов в иных помещениях, зданиях или на иных объектах с согласия собственников или владельцев данных объектов и с соблюдением установленных ими условий."],
["30","Размещение агитационных материалов на объекте, находящемся в государственной или муниципальной собственности либо в собственности организации,…","","","30. Размещение агитационных материалов на объекте, находящемся в государственной или муниципальной собственности либо в собственности организации, имеющей на день официального опубликования (публикации) решения о назначении выборов, регистрации инициативной группы по проведению референдума в своем уставном (складочном) капитале долю (вклад) Российской Федерации, субъектов Российской Федерации и (или) муниципальных образований, превышающую (превышающий) 30 процентов, осуществляется с соблюдением принципа равенства всех кандидатов, избирательных объединений, инициативной группы по проведению референдума и иных групп участников референдума (пункт 8 статьи 54 Закона об основных гарантиях избирательных прав).\nНарушение данного принципа в отношении зарегистрированных кандидатов, избирательных объединений, инициативной группы по проведению референдума, иных групп участников референдума может служить основанием для привлечения юридических лиц, осуществляющих полномочия собственников объектов, находящихся в государственной или муниципальной собственности либо имеющих на день официального опубликования (публикации) решения о назначении выборов, регистрации инициативной группы по проведению референдума в своем уставном (складочном) капитале долю (вклад) Российской Федерации, субъектов Российской Федерации и (или) муниципальных образований, превышающую (превышающий) 30 процентов, а также их должностных лиц к административной ответственности по статье 5.48 КоАП РФ."],
["31","К субъектам административной ответственности по части 2 статьи 5.12 КоАП РФ могут быть отнесены кандидаты, избирательные объединения, имеющие статус…","","","31. К субъектам административной ответственности по части 2 статьи 5.12 КоАП РФ могут быть отнесены кандидаты, избирательные объединения, имеющие статус юридического лица, и их должностные лица, члены и уполномоченные представители инициативных групп по проведению референдума, иных групп участников референдума, а также физические и юридические лица, которые осуществляют деятельность по размещению агитационных материалов как по просьбе, поручению или от имени кандидата, избирательного объединения, инициативной группы по проведению референдума или иной группы участников референдума, так и по собственной инициативе, виновные в допущенных нарушениях (пункты 1, 4 статьи 48, пункт 1 статьи 54 Закона об основных гарантиях избирательных прав)."],
["32","Судам при разрешении дел об административных правонарушениях, связанных с нарушением порядка опубликования результатов опросов общественного мнения,…","","","32. Судам при разрешении дел об административных правонарушениях, связанных с нарушением порядка опубликования результатов опросов общественного мнения, следует учитывать, что под опросом общественного мнения, связанного с выборами и референдумом, следует понимать метод получения информации (выявления мнений граждан) относительно проводимых (проведенных) выборов, кандидатов, избирательных объединений или референдума путем очного или заочного обращения к группе людей с вопросами, касающимися предмета исследования.\nПорядок опубликования (обнародования) результатов опросов общественного мнения, связанных с выборами и референдумами, предусматривает опубликование (обнародование) вместе с результатами опроса определенных законом сведений, а также период, в течение которого опубликование (обнародование) результатов опросов общественного мнения запрещается (пункты 2 и 3 статьи 46 Закона об основных гарантиях избирательных прав).\nПри опубликовании (обнародовании) результатов опроса общественного мнения лица, их публикующие (обнародующие), обязаны указать организацию, проводившую опрос, время его проведения, число опрошенных (выборку), метод сбора информации, регион, где проводился опрос, точную формулировку вопроса, как он был задан при проведении опроса, статистическую оценку возможной погрешности, лицо (лиц), заказавшее (заказавших) проведение опроса и оплатившее (оплативших) указанную публикацию (обнародование) (пункт 2 статьи 46 Закона об основных гарантиях избирательных прав).\nПериод, в течение которого запрещается опубликование (обнародование) результатов опросов общественного мнения, прогнозов результатов выборов и референдумов, иных исследований, связанных с проводимыми выборами и референдумами, в том числе их размещение в информационно-телекоммуникационной сети, включает в себя пять дней до дня (последнего дня) голосования, а также день (последний день) голосования до момента окончания голосования на территории соответствующего избирательного округа, округа референдума (пункт 3 статьи 46 Закона об основных гарантиях избирательных прав).\nПри определении соответствующего периода необходимо руководствоваться правилами исчисления сроков, закрепленными в законодательстве о выборах и референдумах (пункт 2 статьи 11.1 Закона об основных гарантиях избирательных прав).\nНапример, если последним днем голосования на выборах является 25 число месяца, то начиная с ноля часов по местному времени 20 числа этого месяца действует запрет на опубликование (обнародование) результатов опросов общественного мнения, прогнозов результатов выборов, иных исследований, связанных с проводимыми выборами (пункт 3 статьи 63.1 Закона об основных гарантиях избирательных прав)."],
["33","При наличии у допустившего нарушение порядка опубликования (обнародования) результатов опросов общественного мнения лица цели выразить предпочтение…","","","33. При наличии у допустившего нарушение порядка опубликования (обнародования) результатов опросов общественного мнения лица цели выразить предпочтение какому-либо кандидату, избирательному объединению такое опубликование (обнародование) может быть признано предвыборной агитацией и повлечь его привлечение к административной ответственности по соответствующей статье (по соответствующим статьям) КоАП РФ (статьи 5.5, 5.8, 5.10, 5.11, 5.12) (подпункт \"б\" пункта 2 статьи 48 Закона об основных гарантиях избирательных прав)."],
["34","В случае, если в результате одного действия лицом были совершены административные правонарушения, предусмотренные статьями 5.10, 5.11 и (или) 5.12…","","","34. В случае, если в результате одного действия лицом были совершены административные правонарушения, предусмотренные статьями 5.10, 5.11 и (или) 5.12 КоАП РФ (например, проведение предвыборной агитации иностранным гражданином вне агитационного периода, установленного законодательством о выборах и референдумах), такое лицо подлежит привлечению к административной ответственности за совершенные правонарушения с назначением административного наказания по правилам части 2 статьи 4.4 Кодекса."],
["35","По общему правилу, дела об административных правонарушениях, предусмотренных статьями 5.1 - 5.25, 5.45 - 5.52, 5.56, 5.58, 5.69 КоАП РФ (далее - дела…","","","35. По общему правилу, дела об административных правонарушениях, предусмотренных статьями 5.1 - 5.25, 5.45 - 5.52, 5.56, 5.58, 5.69 КоАП РФ (далее - дела об административных правонарушениях, посягающих на избирательные права), разрешаются мировыми судьями (абзац шестой части 3 статьи 23.1 КоАП РФ). Исключение составляют, в частности, дела об административных правонарушениях, производство по которым осуществлялось в форме административного расследования, полномочиями по рассмотрению которых наделены судьи районных судов, а также дела об административных правонарушениях, предусмотренных статьями 5.1 - 5.25, 5.45 - 5.52, 5.56 КоАП РФ и совершенных военнослужащими, гражданами, призванными на военные сборы, которые рассматриваются судьями гарнизонных военных судов (часть 2 статьи 2.5, абзацы первый и второй части 3 статьи 23.1, часть 1 статьи 28.7 КоАП РФ).\nСрок давности привлечения к административной ответственности по делам об административных правонарушениях, посягающих на избирательные права, составляет один год (часть 1 статьи 4.5 КоАП РФ)."],
["36","Судам при разрешении дел об административных правонарушениях, посягающих на избирательные права, следует учитывать особенности привлечения к…","","","36. Судам при разрешении дел об административных правонарушениях, посягающих на избирательные права, следует учитывать особенности привлечения к административной ответственности лиц, выполняющих определенные государственные функции (часть 2 статьи 1.4 КоАП РФ).\nВ частности, законодательством о выборах и референдумах закреплено, что член комиссии с правом решающего голоса не может быть подвергнут административному наказанию, налагаемому в судебном порядке, без согласия прокурора субъекта Российской Федерации; член Центральной избирательной комиссии Российской Федерации с правом решающего голоса, председатель избирательной комиссии субъекта Российской Федерации не могут быть подвергнуты административному наказанию, налагаемому в судебном порядке, без согласия Генерального прокурора Российской Федерации; зарегистрированный кандидат не может быть подвергнут административному наказанию, налагаемому в судебном порядке, без согласия прокурора (соответственно уровню выборов) (пункты 18, 18.1 статьи 29, пункт 4 статьи 41 Закона об основных гарантиях избирательных прав, пункт 6 статьи 42 Федерального закона от 10 января 2003 года N 19-ФЗ \"О выборах Президента Российской Федерации\", часть 3 статьи 54 Федерального закона \"О выборах депутатов Государственной Думы Федерального Собрания Российской Федерации\").\nПри выяснении судьей вопроса об обеспечении указанных гарантий необходимо исходить из того, что по смыслу приведенных положений соответствующее согласие должно быть получено до вынесения постановления о назначении административного наказания.\nУтрата лицом соответствующего статуса до момента вынесения постановления о назначении административного наказания свидетельствует о прекращении действия особых условий привлечения к административной ответственности."],
["37","Следует иметь в виду, что прокурор наделен полномочиями по возбуждению дел об административных правонарушениях, предусмотренных статьями 5.1, 5.6,…","","","37. Следует иметь в виду, что прокурор наделен полномочиями по возбуждению дел об административных правонарушениях, предусмотренных статьями 5.1, 5.6, 5.7, 5.21, 5.23 - 5.25, 5.45, 5.46, 5.48, 5.52, 5.58 КоАП РФ, а также при осуществлении надзора за соблюдением Конституции Российской Федерации и исполнением законов, действующих на территории Российской Федерации, вправе возбудить дело о любом другом административном правонарушении, ответственность за которое предусмотрена Кодексом (часть 1 статьи 28.4 КоАП РФ).\nПрокурор извещается о месте и времени рассмотрения дела об административном правонарушении, возбужденного по его инициативе; в случае участия прокурора в рассмотрении дела заслушивается его заключение (часть 2 статьи 25.11, часть 2 статьи 29.7, пункт 9 части 2 статьи 30.6 Кодекса).\nВ то же время присутствие надлежащим образом извещенного о времени и месте судебного заседания прокурора при рассмотрении дела об административном правонарушении, посягающем на избирательные права, в том числе в случае дачи прокурором согласия на применение к лицу, в отношении которого ведется производство по делу, мер административной ответственности, не является обязательным."],
["38","Полномочиями по возбуждению дел об административных правонарушениях, посягающих на избирательные права, также наделены в пределах компетенции…","","","38. Полномочиями по возбуждению дел об административных правонарушениях, посягающих на избирательные права, также наделены в пределах компетенции должностные лица органов внутренних дел (полиции), органа, осуществляющего функции по контролю и надзору в сфере связи, информационных технологий и массовых коммуникаций, а также члены избирательных комиссий, комиссий референдума с правом решающего голоса, уполномоченные избирательными комиссиями, комиссиями референдума (пункты 1, 58 части 2, пункт 1 части 5 статьи 28.3 КоАП РФ).\nКодекс не относит названных должностных лиц к участникам производства по делам об административных правонарушениях, посягающих на избирательные права. Вместе с тем в случае необходимости разрешения возникших вопросов судья может вызвать указанных лиц в судебное заседание в качестве свидетелей (статья 25.6 КоАП РФ)."],
["39","В целях обеспечения эффективной защиты избирательных прав, права на участие в референдумах граждан Российской Федерации, их объединений, обеспечения…","","","39. В целях обеспечения эффективной защиты избирательных прав, права на участие в референдумах граждан Российской Федерации, их объединений, обеспечения установленного порядка организации, проведения выборов и референдумов в Российской Федерации Кодекс закрепляет сокращенные сроки совершения процессуальных действий при производстве по делам об административных правонарушениях, посягающих на избирательные права.\nТакие дела подлежат рассмотрению в пятидневный срок со дня получения судьей протокола об административном правонарушении и других материалов дела (часть 3 статьи 29.6 КоАП РФ). Жалоба на постановление по делу об административном правонарушении, посягающем на избирательные права, также должна быть разрешена в аналогичный срок со дня ее поступления со всеми материалами в суд, правомочный рассматривать жалобу (часть 2 статьи 30.5 КоАП РФ).\nНадлежит учитывать, что сокращенные сроки рассмотрения дел об административных правонарушениях, посягающих на избирательные права, либо жалоб на не вступившие в законную силу постановления по таким делам не подлежат продлению."],
["40","Доказательствами по делам об административных правонарушениях, посягающих на избирательные права и совершенных в информационно-телекоммуникационной…","","","40. Доказательствами по делам об административных правонарушениях, посягающих на избирательные права и совершенных в информационно-телекоммуникационной сети, наряду с протоколом об административном правонарушении могут являться, например, документы, указывающие на неисполнение лицом установленной законодательством о выборах и референдумах обязанности и подтверждающие факт доступа неопределенного круга лиц к информации, размещенной с нарушением требований закона (в частности, материалам, связанным с подготовкой и проведением выборов, референдумов, в том числе агитационным материалам), включая снимок экрана компьютера, мобильного телефона, планшета, содержащий указание адреса интернет-страницы, на которой размещена соответствующая информация, а также дату и время его изготовления.\nВ случаях, если при производстве по делам об административных правонарушениях, посягающих на избирательные права, возникает необходимость в оказании содействия, в частности, в обнаружении, закреплении доказательств, а также в применении технических средств в целях установления наличия или отсутствия события административного правонарушения, виновности лица, привлекаемого к административной ответственности, иных обстоятельств, имеющих значение для правильного разрешения дела, либо необходимость в использовании специальных познаний, для участия в производстве по делу судьей могут быть привлечены специалист и (или) эксперт (статьи 25.8, 25.9, 26.1, 26.2 КоАП РФ)."],
["41","Жалобы на не вступившие в законную силу постановления по делам об указанных правонарушениях могут быть поданы в пятидневный срок со дня вручения или…","","","41. Жалобы на не вступившие в законную силу постановления по делам об указанных правонарушениях могут быть поданы в пятидневный срок со дня вручения или получения копий постановлений (часть 3 статьи 30.3 КоАП РФ).\nОбратить внимание судов на то, что при исчислении данного срока следует исходить из того, что в случае его окончания в нерабочий день последним днем срока считается первый следующий за ним рабочий день (часть 3.1 статьи 4.8 Кодекса). При наличии уважительных причин пропущенный срок обжалования названных постановлений может быть восстановлен.\nПредседатель Верховного Суда Российской Федерации И.Л.ПОДНОСОВА Секретарь Пленума, судья Верховного Суда Российской Федерации В.В.МОМОТОВ"]
];
